// Builds native maps from Gold's terrain (data/terrain.js, generated by tools/gen-terrain.py from tools/goldmap.py snapshots).
// Game.outdoor(key, goldName, { label, theme ("cave"), style, closed, wild, npcs, signs, coords, warps, enter }) -> a town/route with Gold's cells, building footprints,
//   doors and map-edge roads; `style["x,y"]` (a door cell) gives that building's roof/wall/label; doors and roads to maps we have not built yet are
//   closed with a message. Game.indoor(key, goldName, { art, label, npcs, signs, coords, warps, closed }) -> a room with Gold's collision.
// Positions of people and signs are NOT generated: write them from `python3 tools/goldmap.py <Name>` (test/gold.js checks every one).
const closedDoor = (msg, back) => async (s) => { await s.say(msg); await s.move("player", [back]); };
const BACK = { north: 0, south: 1, west: 3, east: 2 }; // the way to step back in after leaving through that edge

const warpsOf = (t, closedMsg) => {
  const warps = [], coords = [];
  for (const w of t.warps) {
    if (w.to) warps.push({ x: w.x, y: w.y, to: w.to, tx: w.tx, ty: w.ty, dir: w.dir });
    else coords.push({ x: w.x, y: w.y, script: closedDoor(closedMsg[w.toConst] || closedMsg.default, t.solid ? (w.y === t.rows - 1 ? 1 : w.y === 0 ? 0 : w.x === 0 ? 3 : 2) : 0) });
  }
  return { warps, coords };
};

Game.outdoor = (key, gold, o) => {
  const t = Game.terrain[gold], closed = { default: "It's closed for now. Come back soon!", ...(o.closed || {}) };
  const { warps, coords } = warpsOf(t, closed);
  for (const e of t.exits) {
    if (e.to) warps.push({ x: e.x, y: e.y, to: e.to, tx: e.tx, ty: e.ty, dir: e.dir });
    else coords.push({ x: e.x, y: e.y, script: closedDoor(closed[e.toName] || `${e.toName.replace(/(\D)(\d)/, "$1 $2").toUpperCase()} is not open yet. Come back soon!`, BACK[e.side]) });
  }
  // a warp that is not a building's door is a cave mouth (dark opening) or, when it leads to a gate, a gate door
  const loose = t.warps.filter((w) => !t.buildings.some((b) => b.doors.some(([x, y]) => x === w.x && y === w.y)));
  const caves = loose.filter((w) => !/GATE/.test(w.toConst)).map((w) => [w.x, w.y]);
  const gates = loose.filter((w) => /GATE/.test(w.toConst)).map((w) => [w.x, w.y]); // a gate house's side door on a map edge (two tiles tall)
  const buildings = (o.theme === "cave" ? [] : t.buildings).map((b) => ({ ...b, ...((o.style || {})[b.doors[0].join()] || {}) }));
  const signs = [...(o.signs || [])];
  Game.register(key, {
    world: { label: o.label, cols: t.cols, rows: t.rows, cells: t.cells, buildings, caves, gates, theme: o.theme },
    wild: o.wild, enter: o.enter,
    warps: [...warps, ...(o.warps || [])], coords: [...coords, ...(o.coords || [])], npcs: o.npcs || [], signs,
  });
};

Game.indoor = (key, gold, o) => {
  const t = Game.terrain[gold];
  const { warps, coords } = warpsOf(t, { default: "It's closed for now.", ...(o.closed || {}) });
  Game.register(key, {
    room: { art: o.art || "roomGrid", theme: o.theme, cols: t.cols, rows: t.rows, label: o.label, kinds: t.kinds, props: t.props },
    solid: t.solid, kinds: t.kinds, tiles: o.tiles, enter: o.enter, warps: [...warps, ...(o.warps || [])], coords: [...coords, ...(o.coords || [])], npcs: o.npcs || [], signs: o.signs || [],
  });
};
